import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS G/H (Day 2) - CephFS: security & multiple instances in a single RADOS cluster","description":"","frontmatter":{"title":"CDS G/H (Day 2) - CephFS: security & multiple instances in a single RADOS cluster","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["CephFS","多实例","安全性","Rados集群","Ceph"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_security_multiple_instances_in_a_single_RADOS_cluster.md","filePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_security_multiple_instances_in_a_single_RADOS_cluster.md","lastUpdated":1780459816000}'),l={name:"posts/2014/CDS_G_H_Day_2_-_CephFS_-_security_multiple_instances_in_a_single_RADOS_cluster.md"};function a(n,_,p,r,o,c){return t(),s("div",null,[..._[0]||(_[0]=[i("<p>会议探讨了在单个Ceph Rados集群中支持多个CephFS文件系统的可能性。讨论了两种方法来实现这一功能：</p><ol><li><p><strong>方法一</strong>： 通过多个MDS映射来分配数据和元数据池，允许集群中存在任意数量的文件系统。这种方法在文件系统代码上更为简单，但在监视器方面需要更多的工作，且无法实现负载均衡。</p></li><li><p><strong>方法二</strong>： 将多个文件系统作为目录实现，并提供一些语法糖来简化操作。这种方法不需要修改监视器，可以利用客户端之间的负载均衡，但需要稳定的MDS实现和文件系统安全设置。</p></li></ol><p>会议强调了安全性期望的重要性，并决定：</p><ol><li>邀请用户提供用例，以便更好地了解不同方法的优势和优先级。</li><li>进一步讨论安全性期望，以确保满足用户的需求。</li></ol><p>后续行动计划包括：</p><ol><li>收集用户用例，并进行分析。</li><li>继续讨论安全性期望，并制定相应的解决方案。</li><li>根据用户需求和安全性期望，选择合适的实现方法。</li></ol>",6)])])}const D=e(l,[["render",a]]);export{u as __pageData,D as default};
